
/* StoreWell status sounds — real MP3 audio playback */
(function(){
  var _snd={
    green:'', red:'', flashgreen:'',
    flashred:'', blue:'', black:'',
    purple:'', yellow:''
  };
  window._swSND={SND:_snd,busFor:function(){return null;}};
  try{ window._swSoundOn = (localStorage.getItem('sw_sound')!=='off'); }catch(e){ window._swSoundOn=true; }
  window.__swSoundRefresh=function(){
    var c=document.getElementById('sw-cc-sound'); if(!c) return;
    var on=window._swSoundOn!==false, sp=c.getElementsByTagName('span');
    if(sp[0]) sp[0].textContent=on?'\uD83D\uDD0A':'\uD83D\uDD07';
    if(sp[1]) sp[1].textContent=on?'SOUND ON':'MUTED';
    c.title=on?'Sound is on — tap to mute':'Muted — tap to turn sound back on';
    c.style.background=on?'linear-gradient(180deg,#63d15f,#2fa02f)':'linear-gradient(180deg,#9aa6b2,#6b7280)';
    c.style.boxShadow=on?'0 5px 0 #1f7a22,0 2px 8px rgba(0,0,0,0.4)':'0 5px 0 #4b5563,0 2px 8px rgba(0,0,0,0.4)';
  };
  window.__swSoundToggle=function(){
    window._swSoundOn = (window._swSoundOn===false);
    try{ localStorage.setItem('sw_sound', window._swSoundOn?'on':'off'); }catch(e){}
    window.__swSoundRefresh();
    if(window._swSoundOn){ try{ window._swPlaySound('blue'); }catch(e){} }
  };
  window._swPlaySound=function(st){
    if(window._swSoundOn===false) return;
    var b64=window._swSND.SND[st]; if(!b64) return;
    try{ var a=new Audio('data:audio/mpeg;base64,'+b64); a.volume=0.7; a.play(); }catch(e){}
  };
})();
